-- create "file_inspections" table
CREATE TABLE "file_inspections" ("id" serial NOT NULL, "status" character varying(16) NOT NULL, "archive_format" character varying(32) NOT NULL DEFAULT '', "solid" boolean NOT NULL DEFAULT false, "volumes" integer NOT NULL DEFAULT 0, "recovery" boolean NOT NULL DEFAULT false, "recovery_percent" integer NOT NULL DEFAULT 0, "name_encoding" character varying(32) NOT NULL DEFAULT '', "file_count" integer NOT NULL DEFAULT 0, "folder_count" integer NOT NULL DEFAULT 0, "unpacked_size" bigint NOT NULL DEFAULT 0, "disc_count" integer NOT NULL DEFAULT 0, "disc_file_count" integer NOT NULL DEFAULT 0, "truncated" boolean NOT NULL DEFAULT false, "verified" boolean NOT NULL DEFAULT false, "scan_engine" character varying(64) NOT NULL DEFAULT '', "signatures_at" timestamp(3) NULL, "scanned_count" integer NOT NULL DEFAULT 0, "scan_skipped" text[] NULL DEFAULT ARRAY[]::text[], "scan_limit" bigint NOT NULL DEFAULT 0, "detections" jsonb NULL, "scanned_at" timestamp(3) NULL, "cleared_at" timestamp(3) NULL, "created" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated" timestamp(3) NOT NULL, "resource_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "file_inspections_resource_id_fkey" FOREIGN KEY ("resource_id") REFERENCES "game_download_resources" ("id") ON UPDATE CASCADE ON DELETE CASCADE);
-- create index "file_inspections_resource_id_idx" to table: "file_inspections"
CREATE INDEX "file_inspections_resource_id_idx" ON "file_inspections" ("resource_id");
-- create "file_inspection_entries" table
CREATE TABLE "file_inspection_entries" ("id" serial NOT NULL, "parent_id" integer NULL, "position" integer NOT NULL DEFAULT 0, "name" text NOT NULL, "kind" character varying(16) NOT NULL, "size" bigint NOT NULL DEFAULT 0, "modified" timestamp(3) NULL, "items" integer NOT NULL DEFAULT 0, "children" integer NOT NULL DEFAULT 0, "encrypted" boolean NOT NULL DEFAULT false, "unreadable" boolean NOT NULL DEFAULT false, "preview" character varying(8) NOT NULL DEFAULT '', "detail" jsonb NULL, "inspection_id" integer NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "file_inspection_entries_inspection_id_fkey" FOREIGN KEY ("inspection_id") REFERENCES "file_inspections" ("id") ON UPDATE CASCADE ON DELETE CASCADE);
-- create index "file_inspection_entries_inspection_id_parent_id_position_idx" to table: "file_inspection_entries"
CREATE INDEX "file_inspection_entries_inspection_id_parent_id_position_idx" ON "file_inspection_entries" ("inspection_id", "parent_id", "position");
-- modify "game_download_resource_files" table
ALTER TABLE "game_download_resource_files" ADD COLUMN "file_sha256" text NULL, ADD COLUMN "inspection_id" integer NULL, ADD CONSTRAINT "game_download_resource_files_inspection_id_fkey" FOREIGN KEY ("inspection_id") REFERENCES "file_inspections" ("id") ON UPDATE CASCADE ON DELETE SET NULL;
-- create index "game_download_resource_files_inspection_id_idx" to table: "game_download_resource_files"
CREATE INDEX "game_download_resource_files_inspection_id_idx" ON "game_download_resource_files" ("inspection_id");
